      exprErrorUnknownControlPrefix:'No hay ningún control llamado «',exprErrorUnknownControlSuffix:'» en esta capa',exprErrorControlNoLayer:'Esta propiedad no pertenece a ninguna capa, así que no tiene controles',exprErrorUnknownLayerPrefix:'No hay ninguna capa llamada «',exprErrorUnknownLayerSuffix:'»',
